        <div class="wpbb-analytics-actions"><a class="button" href="<?php echo esc_url($settings_url); ?>"><?php esc_html_e('Analytics settings', 'wp-bbuilder'); ?></a><a class="button" href="<?php echo esc_url($full_settings_url); ?>"><?php esc_html_e('BBuilder settings', 'wp-bbuilder'); ?></a></div>
    </div>
    <form class="wpbb-range" method="get"><input type="hidden" name="page" value="wpbb-analytics"><label for="wpbb-range"><?php esc_html_e('Range', 'wp-bbuilder'); ?></label><select id="wpbb-range" name="range" onchange="this.form.submit()"><?php foreach ([7,30,90,180,365] as $d): ?><option value="<?php echo esc_attr($d); ?>" <?php selected($days,$d); ?>><?php echo esc_html(sprintf(_n('%d day','%d days',$d,'wp-bbuilder'),$d)); ?></option><?php endforeach; ?></select></form>

    <div class="wpbb-kpis">
