        <div class="wpbb-kpi"><span><?php esc_html_e('Visitors','wp-bbuilder'); ?></span><strong><?php echo esc_html(number_format_i18n($visitors)); ?></strong><em class="<?php echo $visitor_growth >= 0 ? 'up' : 'down'; ?>"><?php echo esc_html(($visitor_growth >= 0 ? '+' : '') . $visitor_growth . '%'); ?></em></div>
        <div class="wpbb-kpi"><span><?php esc_html_e('Sessions','wp-bbuilder'); ?></span><strong><?php echo esc_html(number_format_i18n($sessions)); ?></strong><small><?php esc_html_e('unique local sessions','wp-bbuilder'); ?></small></div>
        <div class="wpbb-kpi"><span><?php esc_html_e('Pages / session','wp-bbuilder'); ?></span><strong><?php echo esc_html(number_format_i18n($pages_per_session,2)); ?></strong><small><?php esc_html_e('engagement depth','wp-bbuilder'); ?></small></div>
    </div>

    <script type="application/json" id="wpbb-analytics-data"><?php echo wp_json_encode(['daily'=>$daily,'countries'=>$countries,'devices'=>$devices,'referrers'=>$referrers], JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT); ?></script>
    <div class="wpbb-analytics-grid wpbb-analytics-grid--2"><div class="wpbb-analytics-panel"><div class="wpbb-panel-title"><h2><?php esc_html_e('Visits & visitors','wp-bbuilder'); ?></h2><span><?php echo esc_html($days . 'd'); ?></span></div><div id="wpbb-chart-traffic" class="wpbb-chart"></div></div><div class="wpbb-analytics-panel"><div class="wpbb-panel-title"><h2><?php esc_html_e('Countries','wp-bbuilder'); ?></h2><span><?php esc_html_e('CDN/proxy header','wp-bbuilder'); ?></span></div><div id="wpbb-chart-countries" class="wpbb-chart"></div></div></div>
    <div class="wpbb-analytics-grid wpbb-analytics-grid--2"><div class="wpbb-analytics-panel"><div class="wpbb-panel-title"><h2><?php esc_html_e('Devices','wp-bbuilder'); ?></h2></div><div id="wpbb-chart-devices" class="wpbb-chart wpbb-chart--small"></div></div><div class="wpbb-analytics-panel"><div class="wpbb-panel-title"><h2><?php esc_html_e('Acquisition sources','wp-bbuilder'); ?></h2></div><div id="wpbb-chart-referrers" class="wpbb-chart wpbb-chart--small"></div></div></div>

    <div class="wpbb-analytics-grid wpbb-analytics-grid--2">
        <div class="wpbb-analytics-panel"><div class="wpbb-panel-title"><h2><?php esc_html_e('Most visited pages','wp-bbuilder'); ?></h2></div><div class="wpbb-table-scroll"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Page','wp-bbuilder'); ?></th><th><?php esc_html_e('Type','wp-bbuilder'); ?></th><th><?php esc_html_e('Views','wp-bbuilder'); ?></th><th><?php esc_html_e('Visitors','wp-bbuilder'); ?></th></tr></thead><tbody><?php if (!$top_pages): ?><tr><td colspan="4"><?php esc_html_e('No visits yet. Generate demo data from Analytics settings or browse the site with tracking enabled.','wp-bbuilder'); ?></td></tr><?php endif; ?><?php foreach ($top_pages as $row): ?><tr><td><strong><?php echo esc_html($row['title'] ?: $row['path']); ?></strong><small><?php echo esc_html($row['path']); ?></small></td><td><?php echo esc_html($row['object_type'] ?: 'page'); ?></td><td><?php echo esc_html(number_format_i18n((int)$row['views'])); ?></td><td><?php echo esc_html(number_format_i18n((int)$row['visitors'])); ?></td></tr><?php endforeach; ?></tbody></table></div></div>
        <div class="wpbb-analytics-panel"><div class="wpbb-panel-title"><h2><?php esc_html_e('Most viewed products','wp-bbuilder'); ?></h2></div><div class="wpbb-table-scroll"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Product','wp-bbuilder'); ?></th><th><?php esc_html_e('Views','wp-bbuilder'); ?></th><th><?php esc_html_e('Visitors','wp-bbuilder'); ?></th></tr></thead><tbody><?php if (!$top_products): ?><tr><td colspan="3"><?php esc_html_e('Product views will appear here automatically.','wp-bbuilder'); ?></td></tr><?php endif; ?><?php foreach ($top_products as $row): ?><tr><td><strong><?php echo esc_html($row['title'] ?: $row['path']); ?></strong><small><?php echo esc_html($row['path']); ?></small></td><td><?php echo esc_html(number_format_i18n((int)$row['views'])); ?></td><td><?php echo esc_html(number_format_i18n((int)$row['visitors'])); ?></td></tr><?php endforeach; ?></tbody></table></div></div>
